// Synthetic, reproducible datasets (seeded). Free to use: generated by Python Quest, no real people.
// They intentionally contain the problems analysts meet in practice: missing values,
// duplicates, inconsistent labels, outliers and skew.
import { rng } from "../stats/math";

const r2 = (v: number) => Math.round(v * 100) / 100;

function toCsv(header: string[], rows: (string | number | null)[][]) {
  return [header.join(","), ...rows.map((r) => r.map((v) => (v === null ? "" : String(v))).join(","))].join("\n") + "\n";
}

export function ventasCsv(): string {
  const r = rng(2024);
  const regiones = ["Norte", "Sur", "Este", "Oeste"];
  const productos: [string, number][] = [
    ["Pociones", 12.5],
    ["Espadas", 85],
    ["Mapas", 20],
    ["Escudos", 60],
  ];
  const rows: (string | number | null)[][] = [];
  let id = 1000;
  for (let d = 0; d < 120; d++) {
    const date = new Date(Date.UTC(2025, 0, 1 + d));
    const iso = date.toISOString().slice(0, 10);
    const n = 2 + r.int(0, 2);
    for (let i = 0; i < n; i++) {
      const [prod, price] = productos[r.int(0, 3)];
      let region: string = regiones[r.int(0, 3)];
      if (r.next() < 0.03) region = region.toLowerCase() + " "; // inconsistent label
      const weekend = date.getUTCDay() === 0 || date.getUTCDay() === 6;
      const units = Math.max(1, Math.round(r.normal(weekend ? 9 : 6, 2.5)));
      const unitsCell: number | null = r.next() < 0.04 ? null : units;
      rows.push([id++, iso, region, prod, unitsCell, price]);
      if (r.next() < 0.02) rows.push([...rows[rows.length - 1]]); // duplicate row
    }
  }
  rows.push([id++, "2025-03-15", "Sur", "Espadas", 140, 85]); // outlier
  return toCsv(["pedido", "fecha", "region", "producto", "unidades", "precio"], rows);
}

export function pacientesCsv(): string {
  const r = rng(77);
  const rows: (string | number | null)[][] = [];
  for (let i = 1; i <= 160; i++) {
    const grupo = i % 2 ? "control" : "tratamiento";
    const edad = Math.round(Math.min(85, Math.max(25, r.normal(56, 11))));
    const sexo = r.next() < 0.52 ? "F" : "M";
    const fumador = r.next() < 0.28 ? 1 : 0;
    const pas0 = r2(r.normal(148 + 0.25 * (edad - 56) + 4 * fumador, 12));
    const efecto = grupo === "tratamiento" ? -9 : -2;
    const pas1 = r2(pas0 + efecto + r.normal(0, 8));
    const evento = r.next() < (grupo === "tratamiento" ? 0.12 : 0.22) + 0.05 * fumador ? 1 : 0;
    rows.push([i, grupo, edad, sexo, fumador, pas0, r.next() < 0.03 ? null : pas1, evento]);
  }
  return toCsv(["id", "grupo", "edad", "sexo", "fumador", "pas_inicial", "pas_final", "evento"], rows);
}

export function estudiantesCsv(): string {
  const r = rng(5150);
  const rows: (string | number)[][] = [];
  for (let i = 1; i <= 200; i++) {
    const horas = r2(Math.max(0, r.normal(6, 3)));
    const asistencia = r2(Math.min(1, Math.max(0.3, r.normal(0.82, 0.12))));
    const previa = r2(Math.min(10, Math.max(0, r.normal(6, 1.6))));
    const nota = r2(Math.min(10, Math.max(0, 1 + 0.35 * horas + 3 * asistencia + 0.35 * previa + r.normal(0, 1.1))));
    rows.push([i, horas, asistencia, previa, nota, nota >= 5 ? 1 : 0]);
  }
  return toCsv(["id", "horas_estudio", "asistencia", "nota_previa", "nota_final", "aprobado"], rows);
}

export function climaCsv(): string {
  const r = rng(31);
  const rows: (string | number)[][] = [];
  for (let d = 0; d < 365; d++) {
    const date = new Date(Date.UTC(2025, 0, 1 + d)).toISOString().slice(0, 10);
    const temp = r2(14 + 9 * Math.sin(((d - 100) / 365) * 2 * Math.PI) + r.normal(0, 2.2));
    const lluvia = r.next() < 0.3 ? r2(r.exponential(1 / 6)) : 0;
    rows.push([date, temp, lluvia]);
  }
  return toCsv(["fecha", "temperatura", "lluvia_mm"], rows);
}

export const DATASETS = [
  { file: "ventas.csv", title: "Ventas de la tienda del reino", make: ventasCsv, description: "Pedidos de 120 días: región, producto, unidades y precio. Contiene faltantes, duplicados, etiquetas inconsistentes y un atípico." },
  { file: "pacientes.csv", title: "Ensayo clínico sintético", make: pacientesCsv, description: "160 pacientes asignados alternadamente a control o tratamiento; presión arterial sistólica antes y después, y un evento binario. Datos inventados con fines educativos." },
  { file: "estudiantes.csv", title: "Rendimiento de estudiantes", make: estudiantesCsv, description: "Horas de estudio, asistencia, nota previa y nota final de 200 estudiantes ficticios." },
  { file: "clima.csv", title: "Clima diario", make: climaCsv, description: "Temperatura y lluvia diarias de un año en una ciudad imaginaria, con estacionalidad." },
] as const;

const cache: Record<string, string> = {};
export function dataset(file: string): string {
  const d = DATASETS.find((x) => x.file === file);
  if (!d) throw new Error(`Dataset desconocido: ${file}`);
  return (cache[file] ??= d.make());
}

/** Parse a simple CSV (no quoted commas) into header + rows of strings. */
export function parseCsv(text: string) {
  const lines = text.trim().split("\n");
  const header = lines[0].split(",");
  const rows = lines.slice(1).map((l) => l.split(","));
  return { header, rows };
}
